function validate([squares]) {
  if (!Array.isArray(squares) || squares.length < 1 || squares.length > 50000) return 'squares holds 1 to 5 * 10^4 squares.';
  let total = 0;
  for (const square of squares) {
    if (!Array.isArray(square) || square.length !== 3 || !square.every(Number.isInteger)) return 'Each square is [x, y, l] with whole numbers.';
    const [x, y, l] = square;
    if (x < 0 || x > 1e9 || y < 0 || y > 1e9) return 'x and y are between 0 and 10^9.';
    if (l < 1 || l > 1e9) return 'l is between 1 and 10^9.';
    total += l * l;
  }
  if (total > 1e15) return 'The areas of the squares add up to more than 10^15.';
  return null;
}

