function separateSquares(squares) {
  const xs = [...new Set(squares.flatMap((square) => [square[0], square[0] + square[2]]))].sort((a, b) => a - b);
  const index = new Map(xs.map((x, i) => [x, i]));
  const events = [];
  for (const [x, y, side] of squares) {
    events.push([y, 1, x, x + side]);
    events.push([y + side, -1, x, x + side]);
  }
  events.sort((a, b) => a[0] - b[0]);
  const count = new Array(4 * xs.length).fill(0);
  const covered = new Array(4 * xs.length).fill(0);

  function update(node, low, high, from, to, delta) {
    if (to < low || high < from) return;
    if (from <= low && high <= to) {
      count[node] += delta;
    } else {
      const mid = (low + high) >> 1;
      update(2 * node, low, mid, from, to, delta);
      update(2 * node + 1, mid + 1, high, from, to, delta);
    }
    if (count[node] > 0) covered[node] = xs[high + 1] - xs[low];
    else if (low === high) covered[node] = 0;
    else covered[node] = covered[2 * node] + covered[2 * node + 1];
  }

  const strips = [];
  let total = 0;
  for (let i = 0; i + 1 < events.length; i++) {
    const [y, delta, left, right] = events[i];
    update(1, 0, xs.length - 2, index.get(left), index.get(right) - 1, delta);
    const area = covered[1] * (events[i + 1][0] - y);
    strips.push([y, covered[1], area]);
    total += area;
  }

  const half = total / 2;
  let below = 0;
  let k = 0;
  while (below + strips[k][2] < half) {
    below += strips[k][2];
    k++;
  }
  const [bottom, width] = strips[k];
  return bottom + (half - below) / width;
}

