function separateSquares(squares) {
  // Cut the plane at every square edge; each grid cell is either inside some square or outside all of them.
  const xs = [...new Set(squares.flatMap(([x, , l]) => [x, x + l]))].sort((a, b) => a - b);
  const ys = [...new Set(squares.flatMap(([, y, l]) => [y, y + l]))].sort((a, b) => a - b);
  const widths = [];
  for (let j = 0; j + 1 < ys.length; j++) {
    let width = 0;
    for (let i = 0; i + 1 < xs.length; i++) {
      if (squares.some(([x, y, l]) => x <= xs[i] && xs[i + 1] <= x + l && y <= ys[j] && ys[j + 1] <= y + l)) width += xs[i + 1] - xs[i];
    }
    widths.push(width);
  }
  const areaBelow = (t) => {
    let area = 0;
    for (let j = 0; j + 1 < ys.length; j++) area += widths[j] * Math.max(0, Math.min(ys[j + 1], t) - ys[j]);
    return area;
  };
  const total = areaBelow(ys[ys.length - 1]);
  // The area below a line never decreases as the line rises, so bisect for the lowest line with half below it.
  let low = ys[0];
  let high = ys[ys.length - 1];
  for (let step = 0; step < 200 && low < high; step++) {
    const mid = (low + high) / 2;
    if (mid === low || mid === high) break;
    if (2 * areaBelow(mid) >= total) high = mid;
    else low = mid;
  }
  return high;
}

