function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const squares = [];
  if (size === 'small') {
    const n = int(1, 6);
    const span = int(1, 4) * 3;
    const maxSide = int(1, 5);
    const copies = rand() < 0.25;
    for (let i = 0; i < n; i++) {
      // Some inputs repeat earlier squares exactly, which must not add any area.
      if (copies && i > 0 && rand() < 0.5) squares.push([...squares[int(0, i - 1)]]);
      else squares.push([int(0, span), int(0, span), int(1, maxSide)]);
    }
    return [squares];
  }
  const n = int(1500, 2000);
  // Every side is at most sqrt(10^15 / n), so the areas add up to at most 10^15.
  const maxSide = Math.floor(Math.sqrt(1e15 / n));
  const mode = int(0, 2);
  if (mode === 0) {
    // Spread over the whole range: few overlaps, wide gaps.
    for (let i = 0; i < n; i++) squares.push([int(0, 1e9), int(0, 1e9), int(1, maxSide)]);
  } else if (mode === 1) {
    // Packed into a small corner: heavy overlaps.
    for (let i = 0; i < n; i++) squares.push([int(0, 2 * maxSide), int(0, 2 * maxSide), int(1, maxSide)]);
  } else {
    // A few horizontal bands with empty space between them.
    const bands = Array.from({ length: int(2, 6) }, () => int(0, 1e9 - maxSide));
    for (let i = 0; i < n; i++) squares.push([int(0, 1e9), bands[int(0, bands.length - 1)] + int(0, 1000), int(1, maxSide)]);
  }
  return [squares];
}
